import{_ as s,o as n,c as a,a2 as i}from"./chunks/framework.CPzUcv0I.js";const h=JSON.parse('{"title":"Architecture Globale du Système","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/dev/architecture.md","filePath":"fr/guide/dev/architecture.md"}'),r={name:"fr/guide/dev/architecture.md"};function o(t,e,c,l,p,d){return n(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="architecture-globale-du-systeme" tabindex="-1">Architecture Globale du Système <a class="header-anchor" href="#architecture-globale-du-systeme" aria-label="Permalink to &quot;Architecture Globale du Système&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Runtime-Electron-blue.svg" alt="Electron"><img src="https://img.shields.io/badge/Node.js-24+-green.svg" alt="Node.js"><img src="https://img.shields.io/badge/Modèle-Processus%20Isolés-orange.svg" alt="Processus"></div><p>Gens-Launcher est l&#39;interface graphique officielle (GUI) de l&#39;écosystème Gens. Conçu sur <strong>Electron</strong>, son rôle principal est d&#39;orchestrer :</p><ol><li>L&#39;authentification sécurisée des joueurs via l&#39;API Microsoft / Xbox.</li><li>Le téléchargement, la vérification d&#39;intégrité et le lancement du jeu Minecraft via le moteur interne <code>gens-core</code>.</li><li>La communication asynchrone avec <strong>Gens-Horizon</strong>, le moteur déporté de synchronisation cloud différentielle.</li></ol><hr><h2 id="modele-de-processus-isoles" tabindex="-1">Modèle de Processus Isolés <a class="header-anchor" href="#modele-de-processus-isoles" aria-label="Permalink to &quot;Modèle de Processus Isolés&quot;">​</a></h2><p>L&#39;architecture respecte scrupuleusement le paradigme natif d&#39;Electron en scindant l&#39;application en trois royaumes étanches :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-------------------------------------------------------------------+</span></span>
<span class="line"><span>|                        MAIN PROCESS (Node.js)                     |</span></span>
<span class="line"><span>|  - main.js : Cycle de vie, fenêtres, CSP globale                  |</span></span>
<span class="line"><span>|  - src/main/ipc-auth.js : Proxy Mojang, tokens Microsoft          |</span></span>
<span class="line"><span>|  - src/main/ipc-game.js : Préparation JVM, child_process execFile |</span></span>
<span class="line"><span>|  - src/main/ipc-horizon.js : Bridge binaire Horizon.exe           |</span></span>
<span class="line"><span>|  - src/main/crypto-utils.js : Primitives PBKDF2 / AES-256-GCM     |</span></span>
<span class="line"><span>+---------------------------------+---------------------------------+</span></span>
<span class="line"><span>                                  |</span></span>
<span class="line"><span>               IPC Asynchrone     | (ipcMain.handle / invoke)</span></span>
<span class="line"><span>               Whitelist Stricte  |</span></span>
<span class="line"><span>                                  v</span></span>
<span class="line"><span>+-------------------------------------------------------------------+</span></span>
<span class="line"><span>|                    SECURITY BRIDGE (preload.js)                   |</span></span>
<span class="line"><span>|  - contextIsolation: true                                         |</span></span>
<span class="line"><span>|  - enforceSandbox() / enforceReadSandbox() : Bloque Zip Slip      |</span></span>
<span class="line"><span>|  - window.api : Seul point d&#39;entrée exposé au DOM                 |</span></span>
<span class="line"><span>+---------------------------------+---------------------------------+</span></span>
<span class="line"><span>                                  |</span></span>
<span class="line"><span>                                  v</span></span>
<span class="line"><span>+-------------------------------------------------------------------+</span></span>
<span class="line"><span>|                   RENDERER PROCESS (Vanilla JS)                   |</span></span>
<span class="line"><span>|  - renderer.js, HTML5, Vanilla CSS                                |</span></span>
<span class="line"><span>|  - Aucune dépendance Node.js directe (require() interdit)         |</span></span>
<span class="line"><span>|  - Gestionnaires UI : AccountUI, InstancesUI, ModsUI, CloudUI     |</span></span>
<span class="line"><span>+-------------------------------------------------------------------+</span></span></code></pre></div><hr><h2 id="description-des-composants" tabindex="-1">Description des Composants <a class="header-anchor" href="#description-des-composants" aria-label="Permalink to &quot;Description des Composants&quot;">​</a></h2><h3 id="_1-main-process-processus-principal" tabindex="-1">1. Main Process (Processus Principal) <a class="header-anchor" href="#_1-main-process-processus-principal" aria-label="Permalink to &quot;1. Main Process (Processus Principal)&quot;">​</a></h3><p>Il s&#39;exécute dans un contexte Node.js complet avec accès au système de fichiers et au réseau bas niveau :</p><ul><li><strong><code>main.js</code></strong> : Point d&#39;entrée de l&#39;application. Initialise les fenêtres <code>BrowserWindow</code>, installe la politique globale <code>Content-Security-Policy</code> (CSP) et charge les modules IPC.</li><li><strong><code>src/main/ipc-auth.js</code></strong> : Gère les flux OAuth2 Device Code et agit comme proxy sécurisé pour interroger les API Mojang (skins et capes) en contournant les restrictions CORS sans exposer le Renderer.</li><li><strong><code>src/main/ipc-game.js</code></strong> : Moteur de lancement. Assemble les arguments JVM, télécharge les bibliothèques et déclenche l&#39;exécution via <code>child_process.execFile</code> (garantissant l&#39;absence d&#39;injection de shell).</li><li><strong><code>src/main/ipc-horizon.js</code></strong> : Passerelle exclusive avec le binaire autonome <code>Horizon.exe</code>. Valide le hash SHA-256 du binaire local par rapport aux releases GitHub officielles (avec cache mémoire de 2 heures) et filtre les arguments via une whitelist stricte.</li><li><strong><code>src/main/crypto-utils.js</code></strong> : Primitives cryptographiques. Clé de chiffrement dérivée par <strong>PBKDF2</strong> (600 000 itérations avec sel aléatoire de 16 octets dans <code>.key_salt</code>) et chiffrement en <strong>AES-256-GCM</strong>.</li></ul><h3 id="_2-le-pont-de-securite-preload" tabindex="-1">2. Le Pont de Sécurité (Preload) <a class="header-anchor" href="#_2-le-pont-de-securite-preload" aria-label="Permalink to &quot;2. Le Pont de Sécurité (Preload)&quot;">​</a></h3><ul><li><strong><code>preload.js</code></strong> : S&#39;exécute dans le Renderer mais configure la passerelle avant de fermer l&#39;accès aux API internes : <ul><li>Expose un objet scellé <code>window.api</code> au DOM via <code>contextBridge.exposeInMainWorld</code>.</li><li>Implémente le bouclier <strong>Software Security Shield</strong> : les fonctions <code>enforceSandbox()</code> et <code>enforceReadSandbox()</code> valident mathématiquement tous les chemins pour prévenir les attaques de type <code>Zip Slip</code> et <code>Path Traversal</code>.</li><li>L&#39;écriture est strictement limitée à <code>%AppData%\\GensLauncher</code>.</li><li>La lecture hors sandbox est restreinte aux répertoires légitimes (<code>.minecraft/</code>, runtimes Java identifiés et dossiers temporaires autorisés).</li></ul></li></ul><h3 id="_3-renderer-process-interface-utilisateur" tabindex="-1">3. Renderer Process (Interface Utilisateur) <a class="header-anchor" href="#_3-renderer-process-interface-utilisateur" aria-label="Permalink to &quot;3. Renderer Process (Interface Utilisateur)&quot;">​</a></h3><ul><li><strong><code>renderer.js</code> / HTML / CSS</strong> : Développé en <strong>Vanilla JS</strong> pour des performances optimales sans framework lourd.</li><li>L&#39;interface n&#39;a aucun accès direct à <code>require()</code> ou à <code>process</code>.</li><li>Toutes les actions système (lancer le jeu, explorer un fichier, synchroniser le cloud) s&#39;effectuent par appels asynchrones sur <code>window.api.invoke()</code>.</li></ul><hr><h2 id="cycle-de-vie-et-performance-asynchrone" tabindex="-1">Cycle de Vie et Performance Asynchrone <a class="header-anchor" href="#cycle-de-vie-et-performance-asynchrone" aria-label="Permalink to &quot;Cycle de Vie et Performance Asynchrone&quot;">​</a></h2><ul><li><strong>Interdiction de <code>sendSync</code> :</strong> Toutes les opérations bloquantes sont asynchrones (<code>ipcRenderer.invoke</code> côté Renderer et <code>ipcMain.handle</code> côté Main). L&#39;interface utilisateur ne se fige jamais, même lors du téléchargement d&#39;un modpack de plusieurs gigaoctets.</li><li><strong>Injection Précoce d&#39;Environnement :</strong> Les métadonnées système (plateforme, architecture, version, appData) sont injectées via <code>BrowserWindow.additionalArguments</code> dès la création de la fenêtre, éliminant tout appel synchrone à l&#39;initialisation.</li></ul>`,20)])])}const m=s(r,[["render",o]]);export{h as __pageData,m as default};
